head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.autoComplete1_onviewchange = function(info) {
    console.log('autoComplete1_onviewchange!!!');
    WebSquare.logger.printLog('onviewchange');
};
scwin.autoComplete1_onafteredit = function() {
    console.log('onafteredit!!!');
};
scwin.setSimulate = function() {
	scwin.simulateWrapper("#autoComplete1_input", "key-sequence", {
		sequence: "bcd"
	});
}		
scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.checkLog = function(text) {
    var string = WebSquare.logger.getLog();
    return string.indexOf(text) > -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete1_input').val('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog('onviewchange')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 15-Jun-2018
    //end
}
